// Daily landing/menu only. The existing game actions and game renderers own play.
function dailyMenuIcon(name) {
  const paths={target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><path d="m12 12 8-8m-4 0h4v4"/>',
    shuffle:'<path d="M3 6h3c5 0 7 12 12 12h3m-4-4 4 4-4 4M3 18h3c2 0 3-2 5-5m3-4c1-2 3-3 4-3h3m-4-4 4 4-4 4"/>',
    compare:'<path d="M7 21V3m-4 4 4-4 4 4M17 3v18m-4-4 4 4 4-4"/>',
    trophy:'<path d="M8 3h8v7a4 4 0 0 1-8 0V3Zm0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 2v5m-4 2h8"/>',
    flame:'<path d="M12 3c1 5 5 5 5 9 2-1 2-3 2-3 4 7 1 12-6 12-6 0-9-4-7-9 1 1 2 2 2 2-2-6 4-7 4-11Z"/>',
    coin:'<circle cx="12" cy="12" r="9"/><path d="M14 7h-4v10h4m-5-5h5"/>',
    check:'<path d="m4 12 5 5L20 6"/>',
    arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'};
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.target}</svg>`;
}
function dailyMenuArt() {
  return `<svg viewBox="0 0 350 280" aria-hidden="true" fill="none"><circle cx="197" cy="137" r="107" fill="#83ac8c" opacity=".18"/><circle cx="197" cy="137" r="126" stroke="#bde0b2" stroke-dasharray="3 9" opacity=".25"/><g transform="rotate(-12 87 120)"><rect x="23" y="70" width="106" height="138" rx="10" fill="#d7e8c7"/><rect x="34" y="81" width="84" height="116" rx="5" stroke="#4e7665" stroke-dasharray="4 4"/><text x="76" y="154" font-family="Manrope, sans-serif" font-weight="800" font-size="56" text-anchor="middle" fill="#315849">?</text></g><g transform="rotate(9 160 155)"><rect x="105" y="113" width="99" height="130" rx="10" fill="#fbf4dc"/><path d="M119 134h36m-36 9h25" stroke="#9da993" stroke-width="3" stroke-linecap="round"/><circle cx="155" cy="184" r="24" stroke="#bf8b45" stroke-width="2"/><text x="155" y="194" font-family="Manrope, sans-serif" font-weight="800" font-size="28" text-anchor="middle" fill="#bf8b45">5</text></g><g transform="rotate(-29 237 117)"><rect x="219" y="99" width="19" height="118" rx="5" fill="#cb9560"/><rect x="172" y="69" width="112" height="38" rx="9" fill="#f5c783"/><path d="M186 69v38m84-38v38" stroke="#c69051" stroke-width="5"/><rect x="196" y="80" width="63" height="15" rx="3" fill="#fce0a9"/></g><ellipse cx="224" cy="249" rx="58" ry="8" fill="#082c24" opacity=".4"/><path d="m296 162 3 10 10 3-10 3-3 10-3-10-10-3 10-3Z" fill="#f5c783"/><path d="m42 37 2 7 7 2-7 2-2 7-2-7-7-2 7-2Z" fill="#a9cc9c"/></svg>`;
}
function dailyMenuMarkup({status,completedRounds,score,playerStats,rewards,edition,date}) {
  const complete=status==='completed',started=status==='in_progress',signedIn=Boolean(account);
  const action=complete?t('View results','Ergebnisse ansehen'):started?t('Continue Daily','Daily fortsetzen'):t('Play Daily','Daily starten');
  const reward=account?.rewardsByMode?.daily,earned=reward?.complete?reward.earned:null;
  const earnedHl=account?.rewardsByMode?.['higher-lower']?.earned||0;
  const dailyMax=rewards.daily+(rewards.dailyScoreBonus||0);
  const statusLabel=complete?t('Completed','Abgeschlossen'):started?t('In progress','In Bearbeitung'):t('Not started','Nicht gestartet');
  const statsValue=value=>value===null?'—':number(value);
  const links=[['/leaderboard','trophy',t('Daily leaderboard','Daily-Rangliste')],...(economyFlags.paletteAuctions?[['/auction-house','target',t('Auction House','Auktionshaus')]]:[])];
  return `<div class="daily-home"><header class="daily-home-heading"><div><h1>Daily<span aria-hidden="true">.</span></h1></div><div class="daily-edition"><span>${t('EDITION','AUSGABE')} #${number(edition)}</span><time datetime="${auctionEscape(date)}">${auctionEscape(new Date(date+'T12:00:00Z').toLocaleDateString(uiLocale(),{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}))}</time></div></header>
    <div class="daily-home-feature"><section class="daily-challenge ${complete?'is-complete':''}" aria-labelledby="daily-challenge-title"><div class="daily-challenge-content"><p class="daily-feature-badge">${dailyMenuIcon(complete?'check':'target')}${statusLabel}</p><h2 id="daily-challenge-title">${complete?t('Daily results','Daily-Ergebnisse'):t('Guess the bids','Gebote schätzen')}</h2><div class="daily-challenge-facts"><span><strong>5</strong>${t('lots','Lose')}</span><span><strong>${number(5000)}</strong>${t('max. points','max. Punkte')}</span><span><strong>${t('1 / day','1 / Tag')}</strong>${t('new challenge','neue Herausforderung')}</span></div><button class="daily-play" type="button" data-action="play">${action}${dailyMenuIcon('arrow')}</button></div><div class="daily-challenge-art">${dailyMenuArt()}</div><div class="daily-challenge-bottom">${complete?`<span>${number(score??0)} / ${number(5000)} ${t('points','Punkte')}</span>`:''}<span>${t('NEXT DAILY','NÄCHSTES DAILY')} <strong data-menu-reset>--:--:--</strong></span></div></section>
    <aside class="daily-reward-panel" aria-labelledby="daily-reward-title"><div class="daily-reward-heading"><h2 id="daily-reward-title">${t('Daily reward','Daily-Belohnung')}</h2><span class="daily-reward-seal" aria-hidden="true">${dailyMenuIcon(complete?'check':'coin')}</span></div><div class="daily-reward-art">${caseArtwork({caseType:'lost-property',caseBadge:'?'})}<span>+ 150 XP</span></div><div class="daily-reward-amount"><strong>${earned===null?`${justizEuro(rewards.daily)}–${number(dailyMax)}`:justizEuro(earned)}</strong><span>${earned===null?t('After 5 lots · includes score bonus','Nach 5 Losen · inklusive Punktebonus'):t('Earned today','Heute verdient')}</span></div><p class="daily-case-reward">${dailyMenuIcon('check')} ${t('1 sealed case','1 versiegelte Kiste')}</p><div class="daily-menu-progress"><div><span>${t('Today’s progress','Heutiger Fortschritt')}</span><strong>${number(completedRounds)} / 5</strong></div><ol aria-label="${t('Daily lots completed','Abgeschlossene Daily-Lose')}">${Array.from({length:5},(_,n)=>`<li class="${n<completedRounds?'is-done':''}" aria-label="${t('Lot','Los')} ${n+1}: ${n<completedRounds?t('completed','abgeschlossen'):t('not completed','offen')}">${n<completedRounds?dailyMenuIcon('check'):String(n+1).padStart(2,'0')}</li>`).join('')}</ol></div>${signedIn?'':`<a class="daily-reward-login" href="/login" data-page>${t('Sign in for rewards','Für Belohnungen anmelden')}${dailyMenuIcon('arrow')}</a><p class="daily-reward-footnote">${t('Sign in before starting. Guest games earn no rewards.','Vor dem Start anmelden. Gastspiele erhalten keine Belohnungen.')}</p>`}</aside></div>
    <section class="daily-other-modes" aria-labelledby="daily-other-title"><div class="daily-section-heading"><h2 id="daily-other-title">${t('Other modes','Weitere Spielmodi')}</h2></div><div class="daily-mode-grid"><article class="daily-mode daily-mode-random"><div class="daily-mode-icon" aria-hidden="true">${dailyMenuIcon('shuffle')}</div><div><h3>${t('Free Play','Freies Spiel')}</h3><p>${t('5 random lots','5 zufällige Lose')}</p><span class="daily-mode-detail">${t('Unlimited · no J€ rewards','Unbegrenzt · keine J€-Belohnungen')}</span></div><button type="button" class="daily-mode-play" data-action="random">${t('Start a free game','Freies Spiel starten')}${dailyMenuIcon('arrow')}</button></article><article class="daily-mode daily-mode-hl"><div class="daily-mode-icon" aria-hidden="true">${dailyMenuIcon('compare')}</div><div><h3>Higher or Lower</h3><p>${t('Which lot sold for more?','Welches Los wurde teurer verkauft?')}</p><span class="daily-mode-detail">${signedIn?`${t('Daily limit','Tageslimit')} ${justizEuro(rewards.higherLowerMax)} · ${t('earned today','heute verdient')}: ${justizEuro(earnedHl)}`:t('J€ rewards require sign-in','J€-Belohnungen erfordern Anmeldung')}</span></div><button type="button" class="daily-mode-play" data-action="higher-lower">${t('Play Higher or Lower','Higher or Lower spielen')}${dailyMenuIcon('arrow')}</button></article></div></section>
    <section class="daily-personal" aria-label="${t('Your Daily stats in this browser','Deine Daily-Statistik in diesem Browser')}"><div class="daily-personal-title"><span>${dailyMenuIcon('flame')}</span><div><h2>${t('Daily statistics','Daily-Statistik')}</h2><small>${t('Saved in this browser','In diesem Browser gespeichert')}</small></div></div><dl><div><dt>${t('Current streak','Aktuelle Serie')}</dt><dd>${playerStats.streak?dayLabel(playerStats.streak):'—'}</dd></div><div><dt>${t('Personal best','Bestwert')}</dt><dd>${statsValue(playerStats.best)}</dd></div><div><dt>${t('Average score','Durchschnitt')}</dt><dd>${statsValue(playerStats.average)}</dd></div></dl></section>
    <nav class="daily-next-links" aria-label="${t('Related pages','Weitere Seiten')}">${links.map(([href,icon,label])=>`<a href="${href}" data-page><span class="daily-next-icon">${dailyMenuIcon(icon)}</span><span><strong>${label}</strong></span>${dailyMenuIcon('arrow')}</a>`).join('')}</nav></div>`;
}
